const K = 0.5522847498;
function roundRect(x, y, w, h, r) {
  var rr = Math.max(0.5, Math.min(r, Math.min(w, h) / 2));
  return [
    ['M', x + rr, y],
    ['L', x + w - rr, y],
    ['Q', x + w, y, x + w, y + rr],
    ['L', x + w, y + h - rr],
    ['Q', x + w, y + h, x + w - rr, y + h],
    ['L', x + rr, y + h],
    ['Q', x, y + h, x, y + h - rr],
    ['L', x, y + rr],
    ['Q', x, y, x + rr, y],
    ['Z']
  ];
}
function ellipse(cx, cy, rx, ry) {
  var ox = rx * K;
  var oy = ry * K;
  return [
    ['M', cx + rx, cy],
    ['C', cx + rx, cy + oy, cx + ox, cy + ry, cx, cy + ry],
    ['C', cx - ox, cy + ry, cx - rx, cy + oy, cx - rx, cy],
    ['C', cx - rx, cy - oy, cx - ox, cy - ry, cx, cy - ry],
    ['C', cx + ox, cy - ry, cx + rx, cy - oy, cx + rx, cy],
    ['Z']
  ];
}
const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '细胞壁' },
      { kind: 'text', payload: '细胞核' },
      { kind: 'text', payload: '液泡' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var s = Math.min(W, H);
    var t = s * 0.022;
    var x0 = W * 0.24;
    var y0 = H * 0.24;
    var cw = W * 0.60;
    var ch = H * 0.66;
    var rad = s * 0.06;
    var wall = roundRect(x0, y0, cw, ch, rad);
    var cyto = roundRect(x0 + t, y0 + t, cw - 2 * t, ch - 2 * t, Math.max(2, rad - t));
    var vcx = W * 0.63;
    var vcy = H * 0.60;
    var vrx = W * 0.13;
    var vry = H * 0.22;
    var vacOut = ellipse(vcx, vcy, vrx, vry);
    var vacIn = ellipse(vcx, vcy, vrx * 0.92, vry * 0.90);
    var ncx = W * 0.36;
    var ncy = H * 0.62;
    var nr = s * 0.075;
    var nucOut = visualSdk.circle(ncx, ncy, nr);
    var nucIn = visualSdk.circle(ncx, ncy, nr * 0.86);
    var nucleolus = visualSdk.circle(ncx + nr * 0.24, ncy - nr * 0.18, nr * 0.32);
    var leadWall = visualSdk.arrow(W * 0.30, H * 0.15, W * 0.40, H * 0.245);
    var leadNuc = visualSdk.arrow(W * 0.335, H * 0.465, ncx - nr * 0.15, ncy - nr * 0.92);
    return {
      schemaVersion: 1,
      sceneId: 'plant-cell',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [
        { id: 'cellWall', commands: wall },
        { id: 'cytoplasm', commands: cyto },
        { id: 'vacuoleOuter', commands: vacOut },
        { id: 'vacuoleInner', commands: vacIn },
        { id: 'nucleusOuter', commands: nucOut },
        { id: 'nucleusInner', commands: nucIn },
        { id: 'nucleolus', commands: nucleolus },
        { id: 'leadWall', commands: leadWall },
        { id: 'leadNucleus', commands: leadNuc }
      ],
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'cellWall', fill: '#7fab47' },
          { type: 'path', pathId: 'cytoplasm', fill: '#eef7dc' },
          { type: 'path', pathId: 'vacuoleOuter', fill: '#96cbe2' },
          { type: 'path', pathId: 'vacuoleInner', fill: '#d8eef9' },
          { type: 'path', pathId: 'nucleusOuter', fill: '#a875ad' },
          { type: 'path', pathId: 'nucleusInner', fill: '#d9bcdf' },
          { type: 'path', pathId: 'nucleolus', fill: '#7d4a86' },
          { type: 'path', pathId: 'leadWall', fill: '#3f5060', stroke: { width: 2, cap: 'round' } },
          { type: 'path', pathId: 'leadNucleus', fill: '#3f5060', stroke: { width: 2, cap: 'round' } },
          { type: 'label', contentId: metrics[0].contentId, anchor: { x: W * 0.28, y: H * 0.10 }, hAlign: 'left', vAlign: 'middle', color: '#3d5a1e' },
          { type: 'label', contentId: metrics[1].contentId, anchor: { x: W * 0.29, y: H * 0.42 }, hAlign: 'left', vAlign: 'middle', color: '#5a2b60' },
          { type: 'label', contentId: metrics[2].contentId, anchor: { x: vcx, y: vcy }, hAlign: 'center', vAlign: 'middle', color: '#0f4b63' }
        ]
      }
    };
  }
};
